{
  "root": "main_stack",
  "state": {
    "itinerary": [
      {
        "dayTitle": "Day 1: Ancient Rome & Trastevere Charm",
        "image": "../assets/r_000530_01_1_Colosseum_in_Rome__Italy_-_April_2007.jpg",
        "icon": "../assets/r_000531_01_2_geo-alt.svg",
        "morningActivity": "Immerse yourself in the Colosseum, Roman Forum, and Palatine Hill. Consider a combined ticket for efficiency.",
        "afternoonActivity": "Explore the picturesque streets of Trastevere, visiting the Basilica di Santa Maria in Trastevere.",
        "foodSuggestion": "Enjoy an authentic Roman dinner in Trastevere, savoring dishes like cacio e pepe or supplì.",
        "actionLabel": "Book Colosseum Tickets",
        "actionUrl": "https://www.coopculture.it/en/tickets/"
      },
      {
        "dayTitle": "Day 2: Vatican City & Papal Splendor",
        "image": null,
        "icon": "../assets/r_000529_01_6_building.svg",
        "morningActivity": "Discover the artistic treasures of the Vatican Museums, the awe-inspiring Sistine Chapel, and the grandeur of St. Peter's Basilica.",
        "afternoonActivity": "Wander through St. Peter's Square and cross Ponte Sant'Angelo to visit Castel Sant'Angelo.",
        "foodSuggestion": "Grab a quick pizza al taglio for lunch, followed by a traditional pasta dinner near the Vatican area.",
        "actionLabel": "Book Vatican Tickets",
        "actionUrl": "https://www.museivaticani.va/content/museivaticani/en.html"
      },
      {
        "dayTitle": "Day 3: Baroque Fountains & Pantheon Majesty",
        "image": "../assets/r_000543_01_5_Fontana_di_Trevi.jpg",
        "icon": "../assets/r_000529_01_4_water.svg",
        "morningActivity": "Toss a coin in the iconic Trevi Fountain, ascend the Spanish Steps, and marvel at the architectural wonder of the Pantheon.",
        "afternoonActivity": "Soak in the artistic ambiance of Piazza Navona and experience the vibrant market at Campo de' Fiori.",
        "foodSuggestion": "Indulge in authentic Italian gelato, enjoy a classic espresso, and dine at a charming trattoria in the city center.",
        "actionLabel": null,
        "actionUrl": null
      },
      {
        "dayTitle": "Day 4: Art, Gardens & Roman Views",
        "image": null,
        "icon": "../assets/r_000531_01_8_tree.svg",
        "morningActivity": "Immerse yourself in masterpieces at the Borghese Gallery (advance booking is highly recommended).",
        "afternoonActivity": "Relax and stroll through the beautiful Villa Borghese gardens, culminating with sunset views from Pincio Terrace.",
        "foodSuggestion": "Sample local delicacies at Testaccio Market for lunch, followed by dinner in the bohemian Monti neighborhood.",
        "actionLabel": "Book Borghese Tickets",
        "actionUrl": "https://galleriaborghese.beniculturali.it/en/"
      },
      {
        "dayTitle": "Day 5: Ancient Catacombs & Departure",
        "image": null,
        "icon": "../assets/r_000531_01_3_signpost-split.svg",
        "morningActivity": "Journey along the historic Appian Way (Via Appia Antica) and explore the ancient Catacombs of Callixtus or Domitilla.",
        "afternoonActivity": "Enjoy a final Roman coffee and pick up any last-minute souvenirs before heading to the airport for departure.",
        "foodSuggestion": "Savor a traditional Roman breakfast, followed by a light lunch before your onward journey.",
        "actionLabel": null,
        "actionUrl": null
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "itinerary_h2",
        "itinerary_table",
        "budget_h3",
        "budget_details_stack",
        "quick_actions_h3",
        "quick_actions_stack",
        "sources_h3",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "5-Day Rome Itinerary: Ancient Wonders & Hidden Gems",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Discover the eternal city with this comprehensive 5-day itinerary, covering iconic landmarks, cultural experiences, and culinary delights."
      },
      "children": []
    },
    "itinerary_h2": {
      "type": "Text",
      "props": {
        "text": "Your Rome Adventure",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayTitle",
        "highlightColumns": ["morningActivity", "foodSuggestion"],
        "columns": [
          { "key": "dayTitle", "label": "Day" },
          { "key": "image", "label": "Visual" },
          { "key": "icon", "label": "Icon" },
          { "key": "morningActivity", "label": "Morning Activity" },
          { "key": "afternoonActivity", "label": "Afternoon Activity" },
          { "key": "foodSuggestion", "label": "Food Suggestion" },
          { "key": "actionLabel", "label": "Action Label" },
          { "key": "actionUrl", "label": "Action URL" }
        ]
      },
      "children": []
    },
    "budget_h3": {
      "type": "Text",
      "props": {
        "text": "Estimated Budget",
        "variant": "h3"
      },
      "children": []
    },
    "budget_details_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "budget_accommodation",
        "budget_food",
        "budget_transport",
        "budget_activities",
        "budget_total"
      ]
    },
    "budget_accommodation": {
      "type": "Text",
      "props": {
        "text": "Accommodation: €80-€150 per night (mid-range hotel)"
      },
      "children": []
    },
    "budget_food": {
      "type": "Text",
      "props": {
        "text": "Food: €40-€70 per day (mix of casual and nice meals)"
      },
      "children": []
    },
    "budget_transport": {
      "type": "Text",
      "props": {
        "text": "Local Transport: €7-€15 per day (metro/bus passes)"
      },
      "children": []
    },
    "budget_activities": {
      "type": "Text",
      "props": {
        "text": "Activities/Entrance Fees: €30-€60 per day (Colosseum, Vatican, etc.)"
      },
      "children": []
    },
    "budget_total": {
      "type": "Text",
      "props": {
        "text": "Total Estimated: €157-€295 per day (excluding flights)",
        "variant": "label"
      },
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "button_flight",
        "button_hotel",
        "button_travel_insurance"
      ]
    },
    "button_flight": {
      "type": "Button",
      "props": {
        "label": "Find Flights to Rome"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/flights"
          }
        }
      }
    },
    "button_hotel": {
      "type": "Button",
      "props": {
        "label": "Book Hotels in Rome"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.booking.com/city/it/rome.html"
          }
        }
      }
    },
    "button_travel_insurance": {
      "type": "Button",
      "props": {
        "label": "Get Travel Insurance"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.worldnomads.com/"
          }
        }
      }
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_rome_tourism",
        "source_travel_guide"
      ]
    },
    "source_rome_tourism": {
      "type": "Button",
      "props": {
        "label": "Official Rome Tourism Board"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.turismoroma.it/en"
          }
        }
      }
    },
    "source_travel_guide": {
      "type": "Button",
      "props": {
        "label": "Lonely Planet Rome Guide"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.lonelyplanet.com/italy/rome"
          }
        }
      }
    }
  }
}
